def calculate_unique_flips(n):
    M = 2 * n + 1

    # We calculate p_k for k = 1 to M
    # p_k = (k(k+1)/2 - 1) mod M

    flipped_positions = set()

    for k in range(1, M + 1):
        # Calculate the triangular number T_k = k(k+1)/2
        T_k = k * (k + 1) // 2

        # Calculate p_k
        p_k = (T_k - 1) % M

        flipped_positions.add(p_k)

    return len(flipped_positions)

results = {}
for n in range(1, 11):
    count = calculate_unique_flips(n)
    M = 2 * n + 1
    results[(M, count)] = True

print("Results (2n+1, Count):")
for (M, count) in results.items():
    print(f"({M}, {count})")
